import os
import re
import sys

KEY_PATTERN = re.compile(r'^[A-Za-z0-9_.\-]+$')


def eprint(msg):
    print(msg, file=sys.stderr)


def main():
    if len(sys.argv) < 3:
        eprint("Error: missing arguments. Usage: {} <config_file> <key>".format(sys.argv[0]))
        return 1
    config_path = sys.argv[1]
    key = sys.argv[2]
    if config_path is None or str(config_path).strip() == "":
        eprint("Error: config file path is missing or empty.")
        return 1
    if key is None or str(key).strip() == "":
        eprint("Error: key name is missing or empty.")
        return 1
    key = str(key).strip()

    if not os.path.exists(config_path):
        eprint("Error: config file not found: {}".format(config_path))
        return 1
    if not os.path.isfile(config_path):
        eprint("Error: config path is not a regular file: {}".format(config_path))
        return 1
    if not os.access(config_path, os.R_OK):
        eprint("Error: config file is not readable: {}".format(config_path))
        return 1
    try:
        with open(config_path, "r", encoding="utf-8", errors="strict") as f:
            content = f.read()
    except (FileNotFoundError, PermissionError, OSError, UnicodeDecodeError) as exc:
        eprint("Error: cannot read config file '{}': {}".format(config_path, exc))
        return 1

    if content.strip() == "":
        eprint("Error: config file is empty: {}".format(config_path))
        return 1

    config = {}
    for lineno, raw_line in enumerate(content.splitlines(), start=1):
        stripped = raw_line.strip()
        if stripped == "":
            continue
        if stripped.startswith("#") or stripped.startswith(";"):
            continue
        if "=" in stripped:
            raw_key, raw_value = stripped.split("=", 1)
        elif ":" in stripped:
            raw_key, raw_value = stripped.split(":", 1)
        else:
            eprint("Error: invalid config format at line {}: missing '=' or ':'.".format(lineno))
            return 1
        parsed_key = raw_key.strip()
        parsed_value = raw_value.strip()
        if parsed_key == "" or not KEY_PATTERN.match(parsed_key):
            eprint("Error: invalid config format at line {}: bad key {!r}.".format(lineno, raw_key.strip()))
            return 1
        if len(parsed_value) >= 2 and parsed_value[0] == parsed_value[-1] and parsed_value[0] in ("\"", "'"):
            parsed_value = parsed_value[1:-1]
        config[parsed_key] = parsed_value

    if key in config:
        print(config[key])
    else:
        print("KEY_NOT_FOUND")
    return 0


if __name__ == "__main__":
    sys.exit(main())
